obj_top;

/*****************************************************************************************
 * 함수명   : BnsPanelToGroupBox()
 * 설명       : Panel의 Round를 위해 파라미터로 넘어온 Panel 의 Class 속성값에 따른 함수를 호출한다.
 *****************************************************************************************/
/**
 * @method
 * @name BnsPanelToGroupBox
 * @description desc
 * @param {string} objPanel desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.BnsPanelToGroupBox = function(objPanel) {
    switch (objPanel.className) {
        case "TopCondition_01":
            scwin.BnsPanelToGroupBox_01(objPanel);
            break;
        case "Tab_01":
            scwin.BnsPanelToGroupBox_01(objPanel);
            break;
        case "Description_01":
            $c.libRoundPanel.PanelToGroupBox_02(objPanel);
            break;
    }

    //-- 추가 시작 
    //-- 패널의 Visibility 속성이 변경되었을 때, 배경 패널의 Visibility도 함께 바뀌도록 한다.
    objPanel.onpropertychange = function() {
        var orgPanel = event.srcElement;
        var backPanel = document.getElementById("__GROUPBOX_BACKGROUND__" + event.srcElement.id);
        if (orgPanel.style.visibility == "hidden") {
            backPanel.style.visibility = "hidden";
        } else {
            backPanel.style.visibility = "";
        }
    };
};





/*****************************************************************************************
 * 함수명   : BnsPanelToGroupBox_01()
 * 설명       : Panel 의 Class 속성값이 TopCondition_01일 경우에 호출되어 Panel의 Round를 적용시킨다.
 *****************************************************************************************/
/**
 * @method
 * @name BnsPanelToGroupBox_01
 * @description desc
 * @param {string} objPanel desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.BnsPanelToGroupBox_01 = function(objPanel) {
    var vLeft = objPanel.style.left;
    var vTop = objPanel.style.top;
    var vWidth = objPanel.style.getStyle("width");
    var vPwidth = objPanel.style.pixelWidth;
    var vPheight = objPanel.style.pixelHeight;
    //--  추가 시작 
    var vId = "__GROUPBOX_BACKGROUND__" + objPanel.id;
    var vVisibility = objPanel.style.visibility;
    //--  추가 끝

    // 라운드 테이블을 Panel 뒤 배경으로 붙인다. (포함관계 없음)
    //--  수정 시작 
    //-- 배경 패널의 ID와 Visibility 속성 정의 추가
    var vTableHtml = '<table id="' + vId + '" border="0" cellspacing="0" cellpadding="0" style="position:absolute;width:' + vWidth + ';left:' + vLeft + ';top:' + vTop + ';visibility:' + vVisibility + ';"><tr><td width="10" height="10"><img src="../../img/bns/img_topleftline_y.gif" width="10" height="10"></td><td height="10" background="../../img/bns/img_leftmiddleline_y.gif"></td><td width="10" height="10"><img src="../../img/bns/img_toprightline_y.gif" width="10" height="10"></td></tr><tr><td background="../../img/bns/img_topcenterline_y.gif">&nbsp;</td><td align="center" bgcolor="f4f0e1">';
    //--  수정 끝

    vTableHtml += '<div style="border:0px solid black;margin:0px;padding:0px;width:' + (vPwidth - 20) + 'px;height:' + (vPheight - 20) + 'px;"></div>';
    vTableHtml += '</td><td background="../../img/bns/img_bottomcenterline_y.gif">&nbsp;</td></tr><tr><td width="10" height="10"><img src="../../img/bns/img_bottomleftline_y.gif" width="10" height="10"></td><td height="10" background="../../img/bns/img_rightmiddleline_y.gif"></td><td><img src="../../img/bns/img_bottomrightline_y.gif" width="10" height="10"></td></tr></table>';
    //alert(vTableHtml);

    objPanel.insertAdjacentHTML("beforeBegin", vTableHtml);
    // 원 Panel의 border 및 background 정보를 없앤다.
    objPanel.style.border = "";
    objPanel.style.setStyle("backgroundcolor", "");
};


/******************************************************************* 
 * 함수명   : fn_SearchExchrt
 * 설명     : 환율조회한다.
 * argument : vScrenID, dtsObj, currTpCd, procTpCd(1:exa db,2:mail)
 *******************************************************************/
/**
 * @method
 * @name fn_SearchExchrt
 * @description desc
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} currTpCd desc
 * @param {string} procTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SearchExchrt = function(vScrenID, dtsObj, currTpCd, procTpCd) {
    var retVal = scwin.fn_BnsCheckExaDb(vScrenID, dtsObj, procTpCd);
    if (retVal == 0) {
        var param = '&{P}V_CURR_TP_CD=' + currTpCd;
        var dsNm = 'BNS_SVR_RUN_INFO';
        var qryId = 'lds.stf.bnscommon.select.readExchrt';
        dtsObj.SyncLoad = "true";
        scwin.fn_SearchBns(vScrenID, dtsObj, dsNm, qryId, param);
        if (dtsObj.getTotalRow() > 0) {
            return dtsObj.getCellData(1, 'EXCHRT');
        }
    }
    return 1;
};


/******************************************************************* 
 * 함수명   : fn_ShowInstAlert
 * 설명     : 정상이 아니면 확인메시지를 보여준다.
 * argument : dtsObj : 기관데이터, rowpos row 위치
 *******************************************************************/
/**
 * @method
 * @name fn_ShowInstAlert
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} rowpos desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ShowInstAlert = function(dtsObj, rowpos) {
    if (dtsObj.getCellData(rowpos, 'INST_STAT_CD') != '1') {
        alert('기관상태가 정상인 기관만 선택 가능 합니다.\n선택을 원할 경우 기관관리화면에서 상태를 변경 후 선택이 가능합니다.');
        return 1;
    }
    return 0;
};


/******************************************************************* 
 * 함수명   : fn_BnsCheckExaDb
 * 설명     : Exa DB 사용가능한지 체크한다.
 * argument : vScrenID, dtsObj, dsNm, qryId, param, procTpCd(1:exa db,2:mail)
 *******************************************************************/
/**
 * @method
 * @name fn_BnsCheckExaDb
 * @description desc
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} procTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_BnsCheckExaDb = function(vScrenID, dtsObj, procTpCd) {
    var msg = '';
    msg += '서비스 이용에 불편을 드려 죄송합니다.';
    msg += '\n잠시후 다시 이용해 주세요.';
    msg += '\n이와 관련해서 문의사항이 있으시면 시스템 담당자에게 연락해 주세요.';

    //exa 조회
    var param = '';
    var dsNm = 'BNS_SVR_RUN_INFO';
    var qryId = 'lds.stf.bnscommon.select.readMailAndExaServiceStat';
    dtsObj.SyncLoad = "true";
    scwin.fn_SearchBns(vScrenID, dtsObj, dsNm, qryId, param);
    var exa = dtsObj.getCellData(1, 'EXA_SVC_RUN_YN');
    var mail = dtsObj.getCellData(1, 'MAIL_SVC_RUN_YN');
    if (procTpCd == '1' && exa != 'Y') {
        alert(msg);
        return 1;
    } else if (procTpCd == '2' && mail != 'Y') {
        alert(msg);
        return 1;
    }
    return 0;
};


/******************************************************************* 
 * 함수명   : fn_SearchBns
 * 설명     : 데이터를 조회한다.
 * argument : vScrenID, dtsObj, dsNm, qryId, param
 *******************************************************************/
/**
 * @method
 * @name fn_SearchBns
 * @description desc
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} dsNm desc
 * @param {string} qryId desc
 * @param {string} param desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SearchBns = function(vScrenID, dtsObj, dsNm, qryId, param) {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=" + dsNm;
    url += "&queryId=" + qryId;
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += param;
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    if (dsNm == 'BNS_INST_INFO') {
        dtsObj.InsertRow(dtsObj.getFocusedRowIndex());
        //fn_ResetCdValue(dtsObj);		

    }
};




/******************************************************************* 
 * 함수명   : fn_SearchBns1
