/******************************************************************* 
 * 함수명   : fn_SetBnsComboToCode
 * 설명     : 2개 이상의 콤보데이터들을 설정한다.
 * 부연		: 코드값이 30개 이하인 것들 권장
 * argument : vScrenID, dtsObj, CD_ID_M
 * 호출시	: 	var arrCid = [];
				arrCid.push({cid: "CD_ID", cnm: "콤보 컴포넌트명"});
				arrCid.push({cid: "CD_ID", cnm: "콤보 컴포넌트명"});
*******************************************************************/
/**
 * @method
 * @name fn_SetBnsComboToCode
 * @description desc
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} arrCid desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SetBnsComboToCode = function(vScrenID, dtsObj, arrCid) {
    var arrCD_ID = "";
    for (var i = 0; i < arrCid.length; i++) {
        arrCid[i].cid = scwin.fn_getMappingColNm(arrCid[i].cid);
        arrCD_ID += "'" + arrCid[i].cid + "',";
    }
    arrCD_ID = arrCD_ID.substring(0, arrCD_ID.length - 1);
    var url = "/CodeAction.do?method=listCodeValueNameM";
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&CD_ID_M=" + arrCD_ID;
    dtsObj.SyncLoad = "true";
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    dtsObj.SyncLoad = "false";
    var stdCbd = "",
        i, j;
    var objCod;
    var cd = '';
    var cdNm = '';
    for (var i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dtsObj.getTotalRow(); j++) {
            cd = dtsObj.getCellData(j, "VALUE");
            cdNm = dtsObj.getCellData(j, "TEXT");
            if (dtsObj.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                //통화구분
                if (dtsObj.getCellData(j, "CD_ENG_NM") == 'CURR_TP_CD') {
                    if (cd == '0' || cd > 5) // jackal_140814 위안화 추가 4->5로 수정 

                    {
                        continue;
                    }
                }
                //시장조치구분코드
                else if (dtsObj.getCellData(j, "CD_ENG_NM") == 'BND_MKTACT_TP_CD') {
                    if (cd == '104' || cd == '105' || cd == '999') {
                        continue;
                    }
                }
                //상장수수료면제사유코드
                else if (dtsObj.getCellData(j, "CD_ENG_NM") == 'BND_LIST_FEE_EXMPT_RSN_CD') {
                    if (cd == '6') continue;
                }
                //발행전국채거래구분코드 jackal_150127 WI시장 일정기간 보여지지 않도록 처리 나중에 삭제해야할 내용 wit 처리를 위해 처리안함.
                //else if(dtsObj.NameValue(j, "CD_ENG_NM") == 'PRESALE_GOVBND_TRD_TP_CD') {
                //	if(cd == '1') continue;
                //}
                strCbd += "," + cd + "^" + cd + ' ' + cdNm;
            }
        }
        objCod.CBData = "^ " + strCbd;
    }
};



/******************************************************************* 
 * 함수명   : fn_SetBnsComboToCode
 * 설명     : 2개 이상의 콤보데이터들을 설정한다.
 * 부연		: 코드값이 30개 이하인 것들 권장
 * argument : vScrenID, dtsObj, CD_ID_M
 * 호출시	: 	var arrCid = [];
				arrCid.push({cid: "CD_ID", cnm: "콤보 컴포넌트명"});
				arrCid.push({cid: "CD_ID", cnm: "콤보 컴포넌트명"});
*******************************************************************/
/**
 * @method
 * @name fn_SetBnsComboToCode1
 * @description desc
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} arrCid desc
 * @param {string} defValue desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SetBnsComboToCode1 = function(vScrenID, dtsObj, arrCid, defValue) {
    var arrCD_ID = "";
    for (var i = 0; i < arrCid.length; i++) {
        arrCid[i].cid = scwin.fn_getMappingColNm(arrCid[i].cid);
        arrCD_ID += "'" + arrCid[i].cid + "',";
    }
    arrCD_ID = arrCD_ID.substring(0, arrCD_ID.length - 1);
    var url = "/CodeAction.do?method=listCodeValueNameM";
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&CD_ID_M=" + arrCD_ID;
    dtsObj.SyncLoad = "true";
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    dtsObj.SyncLoad = "false";
    var stdCbd = "",
        i, j;
    var objCod;
    var cd = '';
    var cdNm = '';
    for (var i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dtsObj.getTotalRow(); j++) {
            cd = dtsObj.getCellData(j, "VALUE");
            cdNm = dtsObj.getCellData(j, "TEXT");
            if (dtsObj.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                //시장조치구분코드
                if (dtsObj.getCellData(j, "CD_ENG_NM") == 'BND_MKTACT_TP_CD') {
                    if (cd == '104' || cd == '105' || cd == '999') {
                        continue;
                    }
                }
                strCbd += "," + cd + "^" + cd + ' ' + cdNm;
            }
        }
        objCod.CBData = "0^" + defValue + strCbd;
    }
};



