    }
    var url = "/bns/BnsCommon.do?method=processTeamleadrConfrm";
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
