/******************************************************************* 
 * 함수명   : fn_ChgAmtToHan()
 * 설명     : 금액 한글 변환 한다.
 * argument : dtsObj
 *******************************************************************/
/**
 * @method
 * @name fn_ChgAmtToHan
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ChgAmtToHan = function(str) {
    if (str == '' || str == undefined) return '';
    var won = new Array();
    var han1 = new Array("", "일", "이", "삼", "사", "오", "육", "칠", "팔", "구");
    var han2 = new Array("", "십", "백", "천");
    var han3 = new Array("", "만", "억", "조", "경");
    var han = '';
    var len = str.length;
    for (var i = len - 1; i >= 0; i--) {
        won[i] = han1[str.substring(len - i - 1, len - i)];
        if (i > 0 && won[i] != '') won[i] += han2[i % 4];
        if (i % 4 == 0) won[i] += han3[i / 4];
    }
    for (var i = len - 1; i >= 0; i--) {
        if (won[i].length == 2) won[i - i % 4] += '-';
        if (won[i].length == 1 && i > 0) won[i] = '';
        if (i % 4 != 0) won[i].replace('일', '');
    }
    won = won.reverse().join('').replace(/-+/g, '');
    return '(' + won + ')';
};


/******************************************************************* 
 * 함수명   : fn_CheckNewListIsuInfo
 * 설명     : 신규상장 종목정보를 체크한다.
 * argument : dtsObj
 *******************************************************************/
/**
 * @method
 * @name fn_CheckNewListIsuInfo
 * @description desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckNewListIsuInfo = function(dtsObj) {
    var msg = "";
    //입력체크
    if (dtsObj.getCellData(1, "ISU_NM") == '') {
        alert("한글기준명을 선택하십시오.");
        return 1;
    }
    var unqIsuNm = dtsObj.getCellData(1, "UNQ_ISU_NM");
    var unqIsuEngNm = dtsObj.getCellData(1, "UNQ_ISU_ENG_NM");
    //고유명 앞 공백 체크 추가
    if (unqIsuNm.substring(0, 1) == ' ') {
        alert('한글고유명 맨앞자리에 공란이 있으니 확인하시기 바랍니다.');
        return 1;
    } else if (unqIsuEngNm.substring(0, 1) == ' ') {
        alert('영문고유명 맨앞자리에 공란이 있으니 확인하시기 바랍니다.');
        return 1;
    }
    var overLen = eval($c.stf.getStringSize(unqIsuNm) - 20);
    if ($c.ut.trim(unqIsuNm) == '') {
        alert("한글 종목고유명을 입력하십시오.");
        return 1;
    } else if (overLen > 0) {
        alert("[ 한글고유명  ] 항목의 최대입력은 [ 20 ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        return 1;
    }
    overLen = eval($c.stf.getStringSize(unqIsuEngNm) - 20);
    if ($c.ut.trim(unqIsuEngNm) == '') {
        alert("영문 종목고유명을 입력하십시오.");
        return 1;
    } else if (overLen > 0) {
        alert("[ 영문고유명  ] 항목의 최대입력은 [ 20 ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        return 1;
    }
    if (dtsObj.getCellData(1, "BND_CLSS_CD") == '') {
        alert("채권분류코드를 선택하십시오.");
        return 1;
    }
    if (dtsObj.getCellData(1, "LIST_DD") == '') {
        alert("상장일을 입력하십시오.");
        return 1;
    }
    if (scwin.fn_CheckDateObj(edt_ListDd, "상장일")) {
        return 1;
    }
    if (dtsObj.getCellData(1, "REDMPT_DD") == '') {
        alert("상환일을 입력하십시오.");
        return 1;
    }
    if (scwin.fn_CheckDateObj(edt_RedmptDd, "상환일")) {
        return 1;
    }
    if (dtsObj.getCellData(1, "LIST_DD") >= dtsObj.getCellData(1, "REDMPT_DD")) {
        alert("상환일보다 상장일이 빠릅니다. 일자를 확인바랍니다.");
        return 1;
    }
    if (dtsObj.getCellData(1, "BND_TP_CD") == '') {
        alert("채권유형을 선택하십시오.");
        return 1;
    }
    if (dtsObj.getCellData(1, "NUSUAL_BND_TP_CD") == '') {
        alert("특이채권유형을 선택하십시오.");
        return 1;
    }
    if (dtsObj.getCellData(1, "TAX_YN") == '') {
        alert("과세여부를 선택하십시오.");
        return 1;
    }
    if (dtsObj.getCellData(1, "BND_INT_PAY_DD_BAS_TP_CD") == '') {
        alert("이자일지급기준구분을 선택하십시오.");
        return 1;
    }
    if (dtsObj.getCellData(1, "INT_MMEND_TP_CD") == '') {
        alert("이자월말구분을 선택하십시오.");
        return 1;
    }

    //특수채체크
    if (dtsObj.getCellData(1, "BND_TP_CD") == 'AB') {
        if (dtsObj.getCellData(1, 'SPECLBND_ISUR_CD') == '') {
            alert('특수채 발행기관 코드가 없습니다.');
            return 1;
        }
    } else {
        dts_IsuInfo.setCellData(1, 'SPECLBND_ISUR_CD', '');
    }

    //신청내용 체크 후 접수내역에서 아래사항을 체크한다.
    if (dtsObj.getCellData(1, "BND_LIST_PROCS_TP_CD") == '1' ||
        dtsObj.getCellData(1, "BND_LIST_PROCS_TP_CD") == '3') {
        return 0;
    }
    if (dtsObj.getCellData(1, "INFLLNK_YN") == '') {
        alert("물가연동채구분을 확인해 주십시오.");
        cmb_InfllnkYn.Focus();
        return 1;
    } else if (dtsObj.getCellData(1, "INFLLNK_YN") == 'Y' &&
        dtsObj.getCellData(1, "ISU_DD_REF_IDX") == '') {
        alert("참조지수를 확인해 주십시오.");
        edt_IsuDdRefIdx.Focus();
        return 1;
    }
    if (dtsObj.getCellData(1, "ISUR_CD") != "GB035") {
        if (dtsObj.getCellData(1, "INFLLNK_YN") == "Y") {
            alert("물가연동채구분은 채권유형이 국채일경우만 입력합니다. 채권유형을 확인해 주십시오.");
            return 1;
        }
        if (dtsObj.getCellData(1, "ISU_DD_REF_IDX") != '') {
            alert("참조지수는 채권유형이 국채일경우만 입력합니다. 채권유형을 확인해 주십시오.");
            return 1;
        }
    }
    //국고채이면 메시지추가
    else {
        if (dtsObj.getCellData(1, "ISU_NM").indexOf("물가") != -1 &&
            dtsObj.getCellData(1, "INFLLNK_YN") != 'Y') {
            alert("물가연동채구분을 확인해 주십시오.");
            return 1;
        }
    }
    if (dtsObj.getCellData(1, "BND_TP_CD") == "MB" && dtsObj.getCellData(1, "MUNIBND_TP_CD") == '') {
        alert("지방채구분을 선택하십시오.");
        return 1;
    }

    // 발행통화가 원화가 아닐 경우 경고창 발생
    // 단 외국채권(151)인 경우 모든 통화에대해 팝업 발생.  2023.08.23 no3
    if (dtsObj.getCellData(1, "CURR_TP_CD") == "") {
        alert("발행통화를 선택하십시오.");
        return 1;
    }
    if (vMktactCd == '151' || (vMktactCd != '151' && dtsObj.getCellData(1, "CURR_TP_CD") != '1')) {
        var currTpCd = cmb_CurrTpCd.getText();
        currTpCd = currTpCd.replace(/[0-9\s]/g, '');
        msg = '발행통화가 "' + currTpCd + '" 로 설정되어 있습니다. 진행하시겠습니까?';
        if (!window.confirm(msg)) return 1;
    }
    var iss_amt = dtsObj.getCellData(1, "ISU_AMT");
    var lst_amt = dtsObj.getCellData(1, "LIST_AMT");
    if (iss_amt == '') iss_amt = "0";
    if (lst_amt == '') lst_amt = "0";
    if (dtsObj.getCellData(1, "CURR_TP_CD") == '' || dtsObj.getCellData(1, "CURR_TP_CD") == '1') {
        //메시지 추가 발행금액이 상장금액보다 크거나 같아야 합니다.
        if (parseInt(iss_amt) < parseInt(lst_amt)) {
            alert("발행금액은 상장금액보다 크거나 같아야 합니다.");
            return 1;
        }
        if (iss_amt <= 100000000) {
            alert("발행금액이 1억원 이하입니다.");
        } else if (iss_amt >= 1000000000000) {
            alert("발행금액이 1조원 이상입니다.");
        }
    }
    //메시지 추가:발행금액 10조원이상 만기가 50년 이상
    //	if(iss_amt >= 10000000000000) {
    //		alert('발행금액이 10조원 이상입니다.');
    //	}
    var isudd = dtsObj.getCellData(1, "ISU_DD").substr(0, 4);
    var redmptdd = dtsObj.getCellData(1, "REDMPT_DD").substr(0, 4);
    if ((parseInt(redmptdd) - parseInt(isudd)) >= 50) {
        alert('만기가 50년 이상입니다.');
    }
    if (dtsObj.getCellData(1, "CURR_TP_CD") == '' ||
        dtsObj.getCellData(1, "CURR_TP_CD") == '1') {
        if (lst_amt <= 100000000) {
            alert("상장금액이 1억원 이하입니다.");
        } else if (lst_amt >= 1000000000000) {
            alert("상장금액이 1조원 이상입니다.");
        }
    }
    if (dtsObj.getCellData(1, "NUSUAL_BND_TP_CD") == '') {
        alert("특이채권유형을 선택하십시오.");
        return 1;
    } else if (dtsObj.getCellData(1, "NUSUAL_BND_TP_CD") == '2') {
        if (dtsObj.getCellData(1, "GRT_YD") == '' &&
            dtsObj.getCellData(1, "ADD_YD") == '') {
            msg = '특이채권유형이 주식관련사채일때 보장수익률 또는 추가수익률을 입력하셔야 합니다.';
            msg += '\n그래도 계속하시겠습니까?';
            if (!window.confirm(msg)) return 1;
        }
    }
    // 분리형BW여부가 체크가 된경우 메세지 확인함. jackal_181210
    else if (dtsObj.getCellData(1, "DETACH_BW_YN") == '1') {
        if (dtsObj.getCellData(1, "GRT_YD") == '' &&
            dtsObj.getCellData(1, "ADD_YD") == '') {
            msg = '분리형BW 일때 보장수익률 또는 추가수익률을 입력하셔야 합니다.';
            msg += '\n그래도 계속하시겠습니까?';
            if (!window.confirm(msg)) return 1;
        }
    }

    //보장수익률존재 시 보장수익률적용일 체크
    if (dtsObj.getCellData(1, "GRT_YD") != '' &&
        (dtsObj.getCellData(1, "NUSUAL_BND_TP_CD") != '3' &&
            dtsObj.getCellData(1, "NUSUAL_BND_TP_CD") != '4')) {
        // 분리형BW여부가 체크가 된 경우 메세지 없음. jackal_181210
        if (dtsObj.getCellData(1, "DETACH_BW_YN") == '1') {

        } else if (dtsObj.getCellData(1, "NUSUAL_BND_TP_CD") != '2') {
            msg = '보장수익률 입력 시 특이채권유형을 주식관련사채로 입력하셔야 합니다.';
            msg += '\n그래도 계속하시겠습니까?';
            if (!window.confirm(msg)) return 1;
        }
        if (dtsObj.getCellData(1, "GRT_YD_STRT_DD") == '') {
            alert('보장수익률 적용일을 입력하셔야 합니다.');
            return 1;
        }
    }

    //추가수익률존재 시 추가수익률적용일 체크
    if (dtsObj.getCellData(1, "ADD_YD") != '') {
        // 분리형BW여부가 체크가 된 경우 메세지 없음. jackal_181210
        if (dtsObj.getCellData(1, "DETACH_BW_YN") == '1') {

        } else if (dtsObj.getCellData(1, "NUSUAL_BND_TP_CD") != '2') {
            msg = '추가수익률 입력 시 특이채권유형을 주식관련사채로 입력하셔야 합니다.';
            msg += '\n그래도 계속하시겠습니까?';
            if (!window.confirm(msg)) return 1;
        }
        if (dtsObj.getCellData(1, "ADD_YD_STRT_DD") == '') {
            alert('추가수익률 적용일을 입력하셔야 합니다.');
            return 1;
        }
    }

    //보증방법체크 추가
    if (dtsObj.getCellData(1, "BND_GUAR_TP_CD") == '1' ||
        dtsObj.getCellData(1, "BND_GUAR_TP_CD") == '5') {
        if (dtsObj.getCellData(1, "GRT_INST_CD") == '') {
            alert('보증사채일 경우 관련기관탭의 보증기관은 필수로 입력하셔야 합니다.');
            return 1;
        }
    }
    if (dtsObj.getCellData(1, "INT_PAY_METHD_CD") == '') {
        alert("이자지급방법을 선택하십시오.");
        return 1;
    }

    /* 확인 */
    if (dtsObj.getCellData(1, "ISU_METHD_INDIRECT") != '1' &&
        dtsObj.getCellData(1, "ISU_METHD_DIRECT") != '1' &&
        dtsObj.getCellData(1, "ISU_METHD_PPBOND") != '1') {
        //2006.11.23 add
        alert("발행방법을 선택하십시오.");
        return 1;
    }

    //류인욱팀장님요구로 사모채도 상장(2006.1130)
    //특수채일경우만 사모가 상장될수가 있고 회사채인경우는 공모로 상장됨
    //사모채 체크 시 알림메시지 추가
    if (dtsObj.getCellData(1, "ISU_METHD_PPBOND") == '1' &&
        dtsObj.getCellData(1, "BND_TP_CD") != "AB") {
        //2006.11.23 add
        if (!window.confirm('발행방법이 사모채로 입력되어있습니다.\n그래도 계속하시겠습니까?')) return 1;

        //    	if(dtsObj.NameValue(1, "BND_TP_CD") != "AB") {
        //    		alert('발행방법이 사모채로 입력되어있습니다.\n사모채는 채권유형이 특수채일때만 입력가능한 항목입니다.');
        //    		return 1;
        //    	}
    }

    //메시지추가 이자지급주기는 이자계산주기보다 크거나 같아야 합니다.
    var unit = dtsObj.getCellData(1, "INT_PAY_UNIT_MMS");
    var calc = dtsObj.getCellData(1, "INT_PAY_CALC_MMS");
    if (unit == '') unit = 0;
    if (calc == '') calc = 0;
    if (parseInt(unit) < parseInt(calc)) {
        if (!window.confirm('이자지급주기는 이자계산주기보다 크거나 같아야 합니다.\n그래도 계속하시겠습니까?')) return 1;
    }
    if (dtsObj.getCellData(1, "HBRDBND_YN") == '') {
        alert("신종자본증권여부를 선택하십시오.");
        return 1;
    } else if (dtsObj.getCellData(1, "HBRDBND_YN") == 'Y') {
        if (dtsObj.getCellData(1, "COND_CAP_SECU_TP_CD") != '') {
            alert('신종자본증권일 경우 조건부자본증권 유형을 선택하실 수 없습니다.');
            return 1;
        }
        //추가:신종자본증권여부에 "Y"일 때 선/후/중순위에 "4.후후순위"가 아닐 경우, 채무변제 후후순위인지 확인하십시오. 그래도 진행하시겠습니까?
        else if (dtsObj.getCellData(1, "DEBT_REPAY_RANK_TP_CD") != '4') {
            if (!window.confirm('채무변제 후후순위인지 확인하십시오.\n그래도 계속하시겠습니까?')) return 1;
        }
    }

    //추가:4.후후순위인데 신종자본증권여부가 "N"일 경우, 신종자본증권여부를 확인하십시오. 그래도 진행하시겠습니까?  
    if (dtsObj.getCellData(1, "DEBT_REPAY_RANK_TP_CD") == '4' &&
        dtsObj.getCellData(1, "HBRDBND_YN") == 'N') {
        if (!window.confirm('신종자본증권여부를 확인하십시오.\n그래도 계속하시겠습니까?')) return 1;
    }

    //주식관련사채 체크 추가
    if (dtsObj.getCellData(1, "NUSUAL_BND_TP_CD") == '2' &&
        dtsObj.getCellData(1, "STK_REL_CORPBND_RGHT_TP_CD") == '') {
        if (!window.confirm('주식관련탭 권리구분을  선택하셔야 합니다.\n그래도 계속하시겠습니까?')) return 1;
    }

    //조건부자본증권 추가
    if (dtsObj.getCellData(1, "COND_CAP_SECU_TP_CD") != '') {
        //전환형이면
        if (dtsObj.getCellData(1, "COND_CAP_SECU_TP_CD") == '1') {
            //특이채권유형이 주식관련사채여야 한다.
            if (dtsObj.getCellData(1, "NUSUAL_BND_TP_CD") != '2') {
                alert('특이채권유형을 주식관련사채로 선택하셔야 합니다.\n특이채권유형을 확인바랍니다.');
                return 1;
            }
            // jackal_15.12.09 이전에 현업이 요청한 내용인것 같은데 신규로 추가될 내용을 어떻게 알고 체크했는지 확인 구부장님 체크 하지 말라고 함.

            //주식관련사채이면 '11 조건부자본증권 전환형'이여야 한다.

            //else if(dtsObj.NameValue(1, "STK_REL_CORPBND_RGHT_TP_CD") != '11') {

            //	alert('주식관련탭 권리구분을 조건부자본증권 전환형으로 선택하셔야 합니다.'); 

            //	return 1;

            //}

        }
        //상각형이면 특이채권유형이 일반사채이여야 한다.
        else if (dtsObj.getCellData(1, "COND_CAP_SECU_TP_CD") == '2' &&
            dtsObj.getCellData(1, "NUSUAL_BND_TP_CD") != '1') {
            alert('특이채권유형을 일반사채로 선택하셔야 합니다.\n특이채권유형을 확인바랍니다.');
            return 1;
        }
    }
    // jackal_15.12.09 이전에 현업이 요청한 내용인것 같은데 신규로 추가될 내용을 어떻게 알고 체크했는지 확인 구부장님 체크 하지 말라고 함.
    //if(dtsObj.NameValue(1, "STK_REL_CORPBND_RGHT_TP_CD") == '11') {
    //	if(dtsObj.NameValue(1, "NUSUAL_BND_TP_CD") != '2') {
    //    	alert('특이채권유형을 주식관련사채로 선택하셔야 합니다.\n특이채권유형을 확인바랍니다.'); 
    //		return 1;    		
    //	}else if(dtsObj.NameValue(1, "COND_CAP_SECU_TP_CD") != '1') {
    //    	alert('조건부자본증권유형을 전환형으로 선택하셔야 합니다.\n조건부자본증권유형을 확인바랍니다.'); 
    //		return 1;    		    		
    //	}
    //}

    //낙찰금리 필터링 추가 ,GB035(국고채권), 한국은행(AB101), 예금보험공사(AB526)
    if (dtsObj.getCellData(1, "BND_MKTACT_TP_CD") != '316') {
        var isurcd = dtsObj.getCellData(1, "ISUR_CD");
        if (dtsObj.getCellData(1, "SCBD_INT") == '' &&
            (isurcd == 'GB035' || isurcd == 'AB101' || isurcd == 'AB526')) {
            if (!window.confirm('낙찰금리란에 값이  없습니다.\n그래도 계속하시겠습니까?')) return 1;
        }
    }
    if (dtsObj.getCellData(1, "REDMPT_METHD_TP_CD") != '2' &&
        dtsObj.getCellData(1, "SPLIT_REDMPT_TP_CD") != '') {
        alert("분할상환탭은 분할상환시에만 입력합니다. 상환방법을 확인바랍니다.");
        return 1;
    }
    if (edt_GrtYd.getValue() != '') {
        if (edt_GrtYd.getValue() >= 20) {
            msg = "" + "보장수익률이 20%이상입니다. " + "\n계속 진행하시겠습니까?";
            if (!window.confirm(msg)) return 1;
        }
        if (edt_ExpRedmptRto.getValue() == '100') {
            msg = "" + "보장수익률이 존재하고, 만기상환율이 100%입니다. " + "\n계속 진행하시겠습니까?";
            if (!window.confirm(msg)) return 1;
        }
    }
    if (cmb_AsstSecutizTpCd.getValue() != '' &&
        (cmb_CreditValuInstCd1.getValue() == '' || cmb_SfValuYn1.getValue() != 'Y') &&
        (cmb_CreditValuInstCd2.getValue() == '' || cmb_SfValuYn2.getValue() != 'Y') &&
        (cmb_CreditValuInstCd3.getValue() == '' || cmb_SfValuYn3.getValue() != 'Y') &&
        (cmb_CreditValuInstCd4.getValue() == '' || cmb_SfValuYn4.getValue() != 'Y')) {
        msg = "" + "유동화채권임에도 SF를 선택하지 않았습니다. " + "\n계속 진행하시겠습니까?";
        if (!window.confirm(msg)) return 1;
    }
    var frnBasIntTpCd1 = dtsObj.getCellData(1, "FRN_BAS_INT_TP_CD1");
    var frnBasIntTpCd2 = dtsObj.getCellData(1, "FRN_BAS_INT_TP_CD2");
    var frnBasIntTpCd3 = dtsObj.getCellData(1, "FRN_BAS_INT_TP_CD3");
    var frnBasIntMisc = dtsObj.getCellData(1, "FRN_BAS_INT_MISC");
    if (frnBasIntTpCd1 != undefined && frnBasIntTpCd1 == '7' && $c.ut.trim(frnBasIntMisc) == "") {
        alert("[변동금리 탭]\n" + "기준금리상세-기타 정보를 입력하세요.");
        return 1;
    }
    if (frnBasIntTpCd2 != undefined && frnBasIntTpCd1 == '4' && $c.ut.trim(frnBasIntTpCd2) == "") {
        alert("[변동금리 탭]\n" + "기준금리상세-발행기관 정보를 입력하세요.");
        return 1;
    }
    if (frnBasIntTpCd3 != undefined &&
        (frnBasIntTpCd3 == '2Z' || frnBasIntTpCd3 == '3Z' || frnBasIntTpCd3 == '4Z' || frnBasIntTpCd3 == '5Z') &&
        $c.ut.trim(frnBasIntMisc) == "") {
        alert("[변동금리 탭]\n" + "기준금리상세-기타 정보를 입력하세요.");
        return 1;
    }
    return 0;
};


/******************************************************************* 
 * 함수명   : fn_CheckNewListIsuInfoWIT
 * 설명     : 신규상장 종목정보를 체크한다.
 * argument : dtsObj
 *******************************************************************/
/**
 * @method
 * @name fn_CheckNewListIsuInfoWIT
 * @description desc
 * @param {string} dtsObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckNewListIsuInfoWIT = function(dtsObj) {
    var msg = "";
    //입력체크		
