            return 1;
        }
        //추가:신종자본증권여부에 "Y"일 때 선/후/중순위에 "4.후후순위"가 아닐 경우, 채무변제 후후순위인지 확인하십시오. 그래도 진행하시겠습니까?
        else if (dtsObj.getCellData(1, "DEBT_REPAY_RANK_TP_CD") != '4') {
            if (!window.confirm('채무변제 후후순위인지 확인하십시오.\n그래도 계속하시겠습니까?')) return 1;
        }
    }

    //추가:4.후후순위인데 신종자본증권여부가 "N"일 경우, 신종자본증권여부를 확인하십시오. 그래도 진행하시겠습니까?  
    if (dtsObj.getCellData(1, "DEBT_REPAY_RANK_TP_CD") == '4' &&
        dtsObj.getCellData(1, "HBRDBND_YN") == 'N') {
        if (!window.confirm('신종자본증권여부를 확인하십시오.\n그래도 계속하시겠습니까?')) return 1;
    }

    //주식관련사채 체크 추가
    if (dtsObj.getCellData(1, "NUSUAL_BND_TP_CD") == '2' &&
        dtsObj.getCellData(1, "STK_REL_CORPBND_RGHT_TP_CD") == '') {
        if (!window.confirm('주식관련탭 권리구분을  선택하셔야 합니다.\n그래도 계속하시겠습니까?')) return 1;
    }

    //조건부자본증권 추가
    if (dtsObj.getCellData(1, "COND_CAP_SECU_TP_CD") != '') {
        //전환형이면
        if (dtsObj.getCellData(1, "COND_CAP_SECU_TP_CD") == '1') {
            //특이채권유형이 주식관련사채여야 한다.
            if (dtsObj.getCellData(1, "NUSUAL_BND_TP_CD") != '2') {
                alert('특이채권유형을 주식관련사채로 선택하셔야 합니다.\n특이채권유형을 확인바랍니다.');
                return 1;
            }
            // jackal_15.12.09 이전에 현업이 요청한 내용인것 같은데 신규로 추가될 내용을 어떻게 알고 체크했는지 확인 구부장님 체크 하지 말라고 함.

            //주식관련사채이면 '11 조건부자본증권 전환형'이여야 한다.

            //else if(dtsObj.NameValue(1, "STK_REL_CORPBND_RGHT_TP_CD") != '11') {

            //	alert('주식관련탭 권리구분을 조건부자본증권 전환형으로 선택하셔야 합니다.'); 

            //	return 1;

            //}

        }
        //상각형이면 특이채권유형이 일반사채이여야 한다.
        else if (dtsObj.getCellData(1, "COND_CAP_SECU_TP_CD") == '2' &&
            dtsObj.getCellData(1, "NUSUAL_BND_TP_CD") != '1') {
            alert('특이채권유형을 일반사채로 선택하셔야 합니다.\n특이채권유형을 확인바랍니다.');
            return 1;
        }
    }
    // jackal_15.12.09 이전에 현업이 요청한 내용인것 같은데 신규로 추가될 내용을 어떻게 알고 체크했는지 확인 구부장님 체크 하지 말라고 함.
    //if(dtsObj.NameValue(1, "STK_REL_CORPBND_RGHT_TP_CD") == '11') {
    //	if(dtsObj.NameValue(1, "NUSUAL_BND_TP_CD") != '2') {
    //    	alert('특이채권유형을 주식관련사채로 선택하셔야 합니다.\n특이채권유형을 확인바랍니다.'); 
    //		return 1;    		
    //	}else if(dtsObj.NameValue(1, "COND_CAP_SECU_TP_CD") != '1') {
    //    	alert('조건부자본증권유형을 전환형으로 선택하셔야 합니다.\n조건부자본증권유형을 확인바랍니다.'); 
    //		return 1;    		    		
    //	}
    //}

    //낙찰금리 필터링 추가 ,GB035(국고채권), 한국은행(AB101), 예금보험공사(AB526)
    //if(dtsObj.NameValue(1, "BND_MKTACT_TP_CD") != '316') {
    //    var isurcd = dtsObj.NameValue(1, "ISUR_CD");
    //    if(dtsObj.NameValue(1, "SCBD_INT") == ''
    //    	&& (isurcd == 'GB035' || isurcd == 'AB101' || isurcd == 'AB526')) {
    //    	if(! window.confirm('낙찰금리란에 값이  없습니다.\n그래도 계속하시겠습니까?')) return 1; 
    //    }    	
    //}

    if (dtsObj.getCellData(1, "REDMPT_METHD_TP_CD") != '2' &&
        dtsObj.getCellData(1, "SPLIT_REDMPT_TP_CD") != '') {
        alert("분할상환탭은 분할상환시에만 입력합니다. 상환방법을 확인바랍니다.");
        return 1;
    }
    if (edt_GrtYd.getValue() != '') {
        if (edt_GrtYd.getValue() >= 20) {
            msg = "" + "보장수익률이 20%이상입니다. " + "\n계속 진행하시겠습니까?";
            if (!window.confirm(msg)) return 1;
        }
        if (edt_ExpRedmptRto.getValue() == '100') {
            msg = "" + "보장수익률이 존재하고, 만기상환율이 100%입니다. " + "\n계속 진행하시겠습니까?";
            if (!window.confirm(msg)) return 1;
        }
    }
    if (cmb_AsstSecutizTpCd.getValue() != '' &&
        (cmb_CreditValuInstCd1.getValue() == '' || cmb_SfValuYn1.getValue() != 'Y') &&
        (cmb_CreditValuInstCd2.getValue() == '' || cmb_SfValuYn2.getValue() != 'Y') &&
        (cmb_CreditValuInstCd3.getValue() == '' || cmb_SfValuYn3.getValue() != 'Y') &&
        (cmb_CreditValuInstCd4.getValue() == '' || cmb_SfValuYn4.getValue() != 'Y')) {
        msg = "" + "유동화채권임에도 SF를 선택하지 않았습니다. " + "\n계속 진행하시겠습니까?";
        if (!window.confirm(msg)) return 1;
    }
    return 0;
};


/******************************************************************* 
 * 함수명   : fn_getMsgChkBndClssAndIsur
 * 설명     : fn_ChkBndClssAndIsur 체크 결과 메시지를 리턴한다.
 * argument : result
 *******************************************************************/
/**
 * @method
 * @name fn_getMsgChkBndClssAndIsur
 * @description desc
 * @param {string} result desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getMsgChkBndClssAndIsur = function(result) {
    var msg = "";
    if (result[0] == 1) {
        msg = "채권분류코드가 발행기관코드와 일치하지 않습니다.\n";
        //msg += "채권분류코드 등을 다시 확인해 주시기 바랍니다.";
        msg += "발행기관 채권분류 관리를 참고하여 확인하시기 바랍니다.";
    } else if (result[0] == 2) {
        msg = "채권분류코드가 채권유형과 일치하지 않습니다.\n";
        msg += "채권분류코드 등을 다시 확인해 주시기 바랍니다.";
    } else if (result[0] == 3) {
        //msg = "채권분류코드가 채권유형 \n또는 주식관련구분 등과 일치하지 않습니다.\n";
        msg = "채권분류코드가 채권유형과 일치하지 않습니다.\n";
        msg += "발행기관 채권분류 관리를 참고하여 확인하시기 바랍니다.";
    } else if (result[0] == 4) {
        msg = "채권분류코드가 주식관련 \n또는 권리구분 등과 일치하지 않습니다.\n";
        msg += "채권분류코드를 다시 확인해 주시기 바랍니다.";
    } else if (result[0] == 5) {
        msg = "채권분류코드가 통화표시와 일치하지 않습니다.\n";
        msg += "채권분류코드를 다시 확인해 주시기 바랍니다.";
    } else if (result[0] == 7) {
        msg = "채권분류코드가 지방채구분 \n또는 발행기관코드와 일치하지 않습니다.\n";
        msg += "채권분류코드를 다시 확인해 주시기 바랍니다.";
    } else if (result[0] == 8) {
        msg = "채권분류코드가 지방채구분과 일치하지 않습니다.\n";
        msg += "채권분류코드를 다시 확인해 주시기 바랍니다.";
    } else if (result[0] == 9) {
        msg = "채권분류코드가 국내채여부(FO 외국채권)와 일치하지 않습니다.\n";
        msg += "채권분류코드를 다시 확인해 주시기 바랍니다.";
    } else if (result[0] == 11) {
        msg = "주식관련권리구분이 분리형인 경우 \n주식관련사채가 아닙니다.\n";
        msg += "관련항목을 확인해주시기 바랍니다.";
    }
    if (result[1] == 6) {
        if (result[0] == 0) {
            msg = "유동화구분이 발행기관과 일치하지 않습니다.";
        } else {
            msg = "\n--------------------------------------------------------------\n";
            msg += "유동화구분이 발행기관과 일치하지 않습니다.";
        }
        msg += "\n유동화구분 등을 다시 확인해 주시기 바랍니다.";
    }
    msg += "\n\n 처리하시겠습니까?";
    return msg;
};


/******************************************************************* 
 * 함수명   : fn_ChkBndClssAndIsur
 * 설명     : 채권분류코드와 발행기관, 채권유형 등과 맞는지 체크한다.
 * argument : dtsObj
 *******************************************************************/
/**
 * @method
 * @name fn_ChkBndClssAndIsur
 * @description desc
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} BND_MKTACT_TP_CD desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ChkBndClssAndIsur = function(vScrenID, dtsObj, BND_MKTACT_TP_CD) {
    var rgtCd = dtsObj.getCellData(1, "STK_REL_CORPBND_RGHT_TP_CD"); //권리구분
    var liqCd = dtsObj.getCellData(1, "ASST_SECUTIZ_TP_CD"); //유동화구분
    var isurCd = dtsObj.getCellData(1, "ISUR_CD"); //발행기관코드
    var isurNm = txb_IsurNm.getValue(); //발행기관명
    var localCd = dtsObj.getCellData(1, "MUNIBND_TP_CD"); //지방채구분
    var bndTpCd = dtsObj.getCellData(1, "BND_TP_CD"); //채권유형
    var mktRsnCd = BND_MKTACT_TP_CD; //시장조치
    var currTpCd = dtsObj.getCellData(1, "CURR_TP_CD"); //통화구분
    var bndClssCd = dtsObj.getCellData(1, "BND_CLSS_CD"); //채권분류코드
    var nusualBndTpCd = dtsObj.getCellData(1, "NUSUAL_BND_TP_CD"); //주식관련
    var ischeck = true;
    if (BND_MKTACT_TP_CD == "203") {
        bndTpCd = dtsObj.getCellData(1, "AFCHG_BND_TP_CD"); //채권유형
        bndClssCd = dtsObj.getCellData(1, "AFCHG_BND_CLASS_CD"); //채권분류코드
        ischeck = false;
    }
    ///////////////////////////////////////////////////////////////////////
    // 1. 통화표시체크
    // 2달러 : 채권분류코드(310000), 3엔화 : 채권분류코드(320000)
    // 그 이외의 통화표시선택하면 주식관련/권리구분 체크로 넘어감.
    // 2. 국내채여부체크
    // 외국채권(FO) : 외국채권(130000)
    // 3. 주식관련/권리구분
    // 주식관련이 주식관련채권(2)를 선택한 경우에만 체크함.
    // 주식관련채권+전환권 : 채권분류코드(116510), 주식관련채권+신주인수권비분리형 : 116520, 주식관련채권+교환권비분리형 : 116530, 주식관련채권+이익참가권 : 116540
    // 주식관련이 주식관련채권 이외의 경우에는 발행기관과 채권유형 체크로 넘어감.
    //////////////////////////////////////////////////////////////////////

    var result = new Array();
    result[0] = 0;
    result[1] = 0;

    /**
     * 외화표시채권 310000, 320000, 330000 삭제됨
     * 스트립채권 411000 삭제됨
     */
    //USD
    if (currTpCd == '2') {
        //달러표시채권
        /**
        if(bndClssCd == "310000")	result[0] = 0;
        else						result[0] = 5;
        result[1] = fn_isLiqCheck(isurCd, isurNm, liqCd);
    	 */
        result[0] = 0;
        result[1] = scwin.fn_isLiqCheck(isurCd, isurNm, liqCd);
    }
    //JPY
    else if (currTpCd == '3') {
        /**
        if(bndClssCd == "320000")	result[0] = 0;
        else						result[0] = 5;
        result[1] = fn_isLiqCheck(isurCd, isurNm, liqCd);
    	 */
        //엔화표시채권
        result[0] = 0;
        result[1] = scwin.fn_isLiqCheck(isurCd, isurNm, liqCd);
    }
    //EUR
    else if (currTpCd == '4') {
        /**
        if(bndClssCd == "330000")	result[0] = 0;
        else						result[0] = 5;
        result[1] = fn_isLiqCheck(isurCd, isurNm, liqCd);
    	 */
        //유로화표시채권
        result[0] = 0;
        result[1] = scwin.fn_isLiqCheck(isurCd, isurNm, liqCd);
    } else {
        //외국채
        if (bndTpCd == "FO") {
            //외국채권
            if (bndClssCd == "130000") result[0] = 0;

            else result[0] = 9;
            result[1] = scwin.fn_isLiqCheck(isurCd, isurNm, liqCd);
        } else {
            /**
             * 무조건 발행기관별 채권분류 체크하기
             */
            result = scwin.fn_isIssinstcd(vScrenID, mktRsnCd, bndTpCd, nusualBndTpCd, localCd, bndClssCd, isurCd, isurNm, liqCd, ischeck);
            if (scwin.fn_checkRgtcd(nusualBndTpCd, rgtCd, mktRsnCd)) {
                result[0] = 10;
                result[1] = 10;
                alert("주식관련여부가 주식관련채권(2)인 \n경우에는 권리구분을 선택하십시오.");
                return result;
            }
            if (nusualBndTpCd == '2' && rgtCd != '') {
                result = scwin.fn_isRgtcd(rgtCd, bndClssCd, isurCd, isurNm, liqCd);
            } else {
                /**
            	 * 상단으로 이동
				result = fn_isIssinstcd(vScrenID, mktRsnCd, bndTpCd, nusualBndTpCd, localCd, bndClssCd, isurCd, isurNm, liqCd, true);
            	 */
            }
        }
    }
    if (result[0] == 10 && result[1] == 10) {
        return 1;
    } else if (result[0] == 0 && result[1] == 0) {
        //skip

    } else {
        if (!window.confirm(scwin.fn_getMsgChkBndClssAndIsur(result))) return 1;
    }
    return 0;
};


/******************************************************************* 
