    // 그 이외의 통화표시선택하면 주식관련/권리구분 체크로 넘어감.
    // 2. 국내채여부체크
    // 외국채권(FO) : 외국채권(130000)
    // 3. 주식관련/권리구분
    // 주식관련이 주식관련채권(2)를 선택한 경우에만 체크함.
    // 주식관련채권+전환권 : 채권분류코드(116510), 주식관련채권+신주인수권비분리형 : 116520, 주식관련채권+교환권비분리형 : 116530, 주식관련채권+이익참가권 : 116540
    // 주식관련이 주식관련채권 이외의 경우에는 발행기관과 채권유형 체크로 넘어감.
    //////////////////////////////////////////////////////////////////////

    var result = new Array();
    result[0] = 0;
    result[1] = 0;

    /**
     * 무조건 발행기관별 채권분류 체크하기
     */
    result = scwin.fn_isIssinstcd(vScrenID, mktRsnCd, bndTpCd, nusualBndTpCd, localCd, bndClssCd, isurCd, isurNm, liqCd, ischeck);
    if (result[0] == 10 && result[1] == 10) {
        return 1;
    } else if (result[0] == 0 && result[1] == 0) {
        //skip

    } else {
        if (!window.confirm(scwin.fn_getMsgChkBndClssAndIsur(result))) return 1;
    }
    return 0;
};


/******************************************************************* 
 * 함수명   : fn_isIssinstcd
 * 설명     : 채권분류코드와 발행기관코드와 맞는지 체크하기
 *******************************************************************/
/**
 * @method
 * @name fn_isIssinstcd
 * @description desc
 * @param {string} vScrenID desc
 * @param {string} mktRsnCd desc
 * @param {string} bndTpCd desc
 * @param {string} nusualBndTpCd desc
 * @param {string} localCd desc
 * @param {string} bndClssCd desc
 * @param {string} isurCd desc
 * @param {string} isurNm desc
 * @param {string} liqCd desc
 * @param {string} isCheck desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_isIssinstcd = function(vScrenID, mktRsnCd, bndTpCd, nusualBndTpCd, localCd, bndClssCd, isurCd, isurNm, liqCd, isCheck) {
    var result = new Array();
    result[0] = '';
    result[1] = '';
    //지방채개별,일괄
    if (mktRsnCd == "121" || mktRsnCd == "122") {
        result = scwin.fn_isLocalcd(localCd, bndClssCd, isurCd, isurNm, liqCd);
    } else {
        var param = '';
        param += "&{P}V_ISUR_CD=" + isurCd;

        //발행기관별 채권분류 체크
        var dsNm = 'BNS_BND_CLSS';
        var qryId = 'lds.stf.bnscommon.select.listByIsurBndClsCheck';
        dts_Temp.syncload = "true";
        scwin.fn_SearchBns(vScrenID, dts_Temp, dsNm, qryId, param);
        if (dts_Temp.getTotalRow() > 0) {
            for (var i = 1; i <= dts_Temp.getTotalRow(); i++) {
                if (bndClssCd == dts_Temp.getCellData(i, "BND_CLSS_CD")) {
                    result[0] = 0;
                    break;
                } else {
                    result[0] = 1;
                }
            }
            if (isCheck) {
                result[1] = scwin.fn_isLiqCheck(isurCd, isurNm, liqCd);
            } else {
                result[1] = 0;
            }
        } else {
            result = scwin.fn_getCheck(bndTpCd, bndClssCd, nusualBndTpCd, isurCd, isurNm, liqCd, isCheck);
        }
    }
    return result;
};


/******************************************************************* 
 * 함수명   : fn_getCheck
 * 설명     : 채권분류코드와 채권유형, 주식관련, 권리구분과 맞는지 체크하기
 *******************************************************************/
/**
 * @method
 * @name fn_getCheck
 * @description desc
 * @param {string} bndTpCd desc
 * @param {string} bndClssCd desc
 * @param {string} nusualBndTpCd desc
 * @param {string} isurCd desc
 * @param {string} isurNm desc
 * @param {string} liqCd desc
 * @param {string} isCheck desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getCheck = function(bndTpCd, bndClssCd, nusualBndTpCd, isurCd, isurNm, liqCd, isCheck) {
    var result = new Array();
    result[0] = 0;
    result[1] = 0;

    //국채
    if (bndTpCd == "GB") {
        //기타국채
        if (bndClssCd == "111900") result[0] = 0;

        else result[0] = 2;
    }
    //특수채
    else if (bndTpCd == "AB") {
        //기타비금융특수채
        if (bndClssCd == "113590") result[0] = 0;

        else result[0] = 2;
    }
    //회사채
    else if (bndTpCd == "CO") {
        //일반채권
        if (nusualBndTpCd == "1") {
            //일반사채
            if (bndClssCd == "116100") result[0] = 0;

            else result[0] = 3;
        }
        //ELS
        else if (nusualBndTpCd == "3") {
            //ELS
            if (bndClssCd == "116600") result[0] = 0;

            else result[0] = 3;
        }
    }
    if (isCheck) {
        result[1] = scwin.fn_isLiqCheck(isurCd, isurNm, liqCd);
    } else {
        result[1] = 0;
    }
    return result;
};


/******************************************************************* 
 * 함수명   : fn_isLocalcd
 * 설명     : 지방채구분 체크하기
 *******************************************************************/
/**
 * @method
 * @name fn_isLocalcd
 * @description desc
 * @param {string} localCd desc
 * @param {string} bndClssCd desc
 * @param {string} isurCd desc
 * @param {string} isurNm desc
 * @param {string} liqCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_isLocalcd = function(localCd, bndClssCd, isurCd, isurNm, liqCd) {
    var result = new Array();
    result[0] = 0;
    result[1] = 0;

    //도시철도공채
    if (localCd == "3") {
        //서울특별시, 서울도시철도공채증권
        if (isurCd == "MB001" && bndClssCd == "112100") result[0] = 0;
        //대전광역시, ~


        else if (isurCd == "MB003" && bndClssCd == "112310") result[0] = 0;

        else if (isurCd == "MB004" && bndClssCd == "112320") result[0] = 0;

        else if (isurCd == "MB005" && bndClssCd == "112330") result[0] = 0;

        else if (isurCd == "MB007" && bndClssCd == "112340") result[0] = 0;

        else if (isurCd == "MB006" && bndClssCd == "112350") result[0] = 0;

        else result[0] = 7;
    }
    //지역개발채
    else if (localCd == "2") {
        if (isurCd == "MB001" && bndClssCd == "112569") result[0] = 0;

        else if (isurCd == "MB003" && bndClssCd == "112501") result[0] = 0;

        else if (isurCd == "MB004" && bndClssCd == "112503") result[0] = 0;

        else if (isurCd == "MB005" && bndClssCd == "112505") result[0] = 0;

        else if (isurCd == "MB006" && bndClssCd == "112507") result[0] = 0;

        else if (isurCd == "MB007" && bndClssCd == "112509") result[0] = 0;

        else if (isurCd == "MB008" && bndClssCd == "112511") result[0] = 0;

        else if (isurCd == "MB002" && bndClssCd == "112551") result[0] = 0;

        else if (isurCd == "MB022" && bndClssCd == "112553") result[0] = 0;

        else if (isurCd == "MB033" && bndClssCd == "112555") result[0] = 0;

        else if (isurCd == "MB044" && bndClssCd == "112557") result[0] = 0;

        else if (isurCd == "MB055" && bndClssCd == "112559") result[0] = 0;

        else if (isurCd == "MB066" && bndClssCd == "112561") result[0] = 0;

        else if (isurCd == "MB077" && bndClssCd == "112563") result[0] = 0;

        else if (isurCd == "MB088" && bndClssCd == "112565") result[0] = 0;

        else if (isurCd == "MB099" && bndClssCd == "112567") result[0] = 0;

        else result[0] = 7;
    }
    //모집지역채
    else if (localCd == "1") {
        //공모 지방채
        if (bndClssCd == "112700") result[0] = 0;

        else result[0] = 8;
    }
    //기타지방채, 기타
    else if (localCd == "4" || localCd == "5") {
        //기타 지방채
        if (bndClssCd == "112900") result[0] = 0;

        else result[0] = 8;
    }
    result[1] = scwin.fn_isLiqCheck(isurCd, isurNm, liqCd);
    return result;
};


/******************************************************************* 
 * 함수명   : fn_isRgtcd
 * 설명     : 주식관련채권 체크하기
 *******************************************************************/
/**
 * @method
 * @name fn_isRgtcd
 * @description desc
 * @param {string} rgtCd desc
 * @param {string} bndClssCd desc
 * @param {string} isurCd desc
 * @param {string} isurNm desc
 * @param {string} liqCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_isRgtcd = function(rgtCd, bndClssCd, isurCd, isurNm, liqCd) {
    var result = new Array();
    result[0] = 0;
    result[1] = 0;

    /**
     * 회사채 116510, 116520, 116530, 116540 삭제됨
     */
    //전환권
    if (rgtCd == "10") {
        //전환사채
        /**
        if(bndClssCd == "116510")	result[0] = 0;
        else						result[0] = 4;
        result[1] = fn_isLiqCheck(isurCd, isurNm, liqCd);
    	 */
        result[0] = 0;
        result[1] = 0;
    }
    //신주인수권(비분리형)
    else if (rgtCd == "22") {
        //신주인수권부사채
        /**
        if(bndClssCd == "116520")	result[0] = 0;
        else						result[0] = 4;
        result[1] = fn_isLiqCheck(isurCd, isurNm, liqCd);
    	 */
        result[0] = 0;
        result[1] = 0;
    }
    //교환권(비분리형)
    else if (rgtCd == "32") {
        //교환사채
        /**
        if(bndClssCd == "116530")	result[0] = 0;
        else						result[0] = 4;
        result[1] = fn_isLiqCheck(isurCd, isurNm, liqCd);
    	 */
        result[0] = 0;
        result[1] = 0;
    }
    //이익참가권
    else if (rgtCd == "40") {
        //이익참가부사채
        /**
        if(bndClssCd == "116540")	result[0] = 0;
        else						result[0] = 4;
        result[1] = fn_isLiqCheck(isurCd, isurNm, liqCd);
    	 */
        result[0] = 0;
        result[1] = 0;
    }
    //신주인수권(분리형), 교환권(분리형)
    else if (rgtCd == "21" || rgtCd == "31") {
        result[0] = 11;
        result[1] = scwin.fn_isLiqCheck(isurCd, isurNm, liqCd);
    }
    return result;
};


/******************************************************************* 
 * 함수명   : fn_checkRgtcd
 * 설명     : 주식관련여부가 주식관련채권인 경우 권리구분 체크하기
 *******************************************************************/
/**
 * @method
 * @name fn_checkRgtcd
 * @description desc
 * @param {string} nusualBndTpCd desc
 * @param {string} rgtCd desc
 * @param {string} mktRsnCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkRgtcd = function(nusualBndTpCd, rgtCd, mktRsnCd) {
    var result = false;
    if (nusualBndTpCd == "2" &&
        (rgtCd == null || rgtCd == '')) {
        if (mktRsnCd == "111" || mktRsnCd == "121" || mktRsnCd == "131" || mktRsnCd == "141" || mktRsnCd == "151") {
            result = true;
        }
    }
    return result;
};


/******************************************************************* 
 * 함수명   : fn_isLiqCheck
 * 설명     : 유동화구분 체크하기
 *******************************************************************/
/**
 * @method
 * @name fn_isLiqCheck
 * @description desc
 * @param {string} isurCd desc
 * @param {string} isurNm desc
 * @param {string} liqCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_isLiqCheck = function(isurCd, isurNm, liqCd) {
    var result = 0;
    //한국주택금융공사,한국주택저당채권유동화(주)
    if (isurCd == "07915" || isurCd == "05749") {
        if (liqCd == null || liqCd == '') result = 6;
        //ABS(채권형), ABS(수익증권형)


        else if (liqCd == "11" || liqCd == "12") result = 6;
    }
    //~유동화전문~회사
    else if (isurCd != "05749" && isurNm.indexOf("유동") != -1) {
        if (liqCd == null || liqCd == "") result = 6;
    } else if (isurNm.indexOf("유동") == -1 && liqCd != '') {
        result = 6;
    }
    return result;
};


/******************************************************************* 
 * 함수명   : fn_IsChecked()
 * 설명     : 체크박스가 선택되었는지 리턴한다.
 * argument : dtsObj, chkNm
 *******************************************************************/
/**
 * @method
 * @name fn_IsChecked
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} chkNm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_IsChecked = function(dtsObj, chkNm) {
    var checkedNm = "CHECKED";
    if (chkNm != '') {
        checkedNm = chkNm;
    }
    var chkCnt = 0;
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        if (dtsObj.getCellData(i, checkedNm) == "T") {
            chkCnt++;
            break;
        }
    }
    if (chkCnt == 0) {
        return false;
    }
    return true;
};


/******************************************************************* 
 * 함수명   : fn_ProcessStdCdReq
 * 설명     : 신규상장 표준코드요청 처리
 * argument : dtsObj, trsObj, bndApplId
 *******************************************************************/
/**
 * @method
 * @name fn_ProcessStdCdReq
 * @description desc
 * @param {string} screnId desc
 * @param {string} dtsObj desc
 * @param {string} trsObj desc
 * @param {string} bndApplId desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ProcessStdCdReq = function(screnId, dtsObj, trsObj, bndApplId) {
    dtsObj.SyncLoad = "true";
    dtsObj.DataID = encodeURI(scwin.fn_getCheckUrl(screnId, '', bndApplId, 'Y'));
    dtsObj.Reset();
    if (dtsObj.getCellData(1, "VALID_STD_CD") == "Y") {
        alert("이미 표준코드가 요청되었습니다.");
    }
    if (!window.confirm("표준코드 요청하시겠습니까?")) return false;
    var url = "/bns/BnsCommon.do?method=processStdCdReq";
    url += "&SCREN_ID=" + screnId;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    var param = "BND_APPL_ID=" + bndApplId;
    param += ", STD_CD_APPL_ID=" + dtsObj.getCellData(1, "STD_CD_APPL_ID");
    trsObj.Action = $c.lce.fn_encodeNSession(url);
    trsObj.KeyName = "toinb_dataid4";
    trsObj.KeyValue = "JSP(I:pInput=" + dtsObj.id + ")";
    trsObj.Parameters = param;
    trsObj.Post();
};


