/******************************************************************* 
 * 함수명   : fn_ChgIsu_ProcessStdCdReq
 * 설명     : 변경상장 표준코드요청 처리
 * argument : screnId, dtsObj, trsObj, bndApplId, dtsObj2, mktactCd, dtsReqObj
 *******************************************************************/
/**
 * @method
 * @name fn_ChgIsu_ProcessStdCdReq
 * @description desc
 * @param {string} screnId desc
 * @param {string} dtsObj desc
 * @param {string} trsObj desc
 * @param {string} bndApplId desc
 * @param {string} dtsObj2 desc
 * @param {string} mktactCd desc
 * @param {string} dtsReqObj desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ChgIsu_ProcessStdCdReq = function(screnId, dtsObj, trsObj, bndApplId, dtsObj2, mktactCd, dtsReqObj) {
    dtsObj.SyncLoad = "true";
    dtsObj.DataID = encodeURI(scwin.fn_getCheckUrl(screnId, '', bndApplId, 'Y'));
    dtsObj.Reset();
    if (dtsObj.getCellData(1, "VALID_STD_CD") == "Y") {
        alert("이미 표준코드가 요청되었습니다."); //return false;

    }
    if (!window.confirm("표준코드 요청하시겠습니까?")) return false;
    dtsReqObj.SetDataHeader("MKTACT_CD:String, BND_APPL_ID:String, STD_CD_APPL_ID:String, ISU_CD:String, BAS_ISU_NM:String, BAS_ISU_ENG_NM:String, BAS_ISU_ABBRV:String, BAS_ISU_ENG_ABBRV:String, UNQ_ISU_NM:String, UNQ_ISU_ENG_NM:String, ISU_LIST_AMT:String, LIST_DD:String, ISU_DD:String, ISUR_CD:String, PRE_ISUR_CD:String, BND_CLSS_CD:String, BND_TP_CD:String, VALID_STD_CD:String");
    var url = "/bns/ChgList.do?method=processStdCdReq";
    url += "&SCREN_ID=" + screnId;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    dtsReqObj.AddRow();
    dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "MKTACT_CD", mktactCd);
    dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "BND_APPL_ID", bndApplId);
    dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "STD_CD_APPL_ID", dtsObj.getCellData(1, "STD_CD_APPL_ID"));
    dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "ISU_CD", dtsObj2.getCellData(1, "ISU_CD"));
    if (mktactCd == "205") {
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "BAS_ISU_NM", dtsObj2.getCellData(1, "BAS_ISU_NM"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "BAS_ISU_ENG_NM", dtsObj2.getCellData(1, "BAS_ISU_ENG_NM"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "BAS_ISU_ABBRV", dtsObj2.getCellData(1, "BAS_ISU_ABBRV"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "BAS_ISU_ENG_ABBRV", dtsObj2.getCellData(1, "BAS_ISU_ENG_ABBRV"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "UNQ_ISU_NM", dtsObj2.getCellData(1, "UNQ_ISU_NM"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "UNQ_ISU_ENG_NM", dtsObj2.getCellData(1, "UNQ_ISU_ENG_NM"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "ISU_LIST_AMT", dtsObj2.getCellData(1, "EXER_AMT"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "LIST_DD", dtsObj2.getCellData(1, "STRT_DD"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "ISU_DD", dtsObj2.getCellData(1, "STRT_DD"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "ISUR_CD", dtsObj2.getCellData(1, "ISUR_CD"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "PRE_ISUR_CD", "");
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "BND_CLSS_CD", "");
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "BND_TP_CD", "");
    } else if (mktactCd == "203") {
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "BAS_ISU_NM", dtsObj2.getCellData(1, "AFCHG_ISU_NM"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "BAS_ISU_ENG_NM", dtsObj2.getCellData(1, "AFCHG_ISU_ENG_NM"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "BAS_ISU_ABBRV", dtsObj2.getCellData(1, "AFCHG_ISU_ABBRV"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "BAS_ISU_ENG_ABBRV", dtsObj2.getCellData(1, "AFCHG_ISU_ENG_ABBRV"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "UNQ_ISU_NM", dtsObj2.getCellData(1, "AFCHG_UNQ_ISU_NM"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "UNQ_ISU_ENG_NM", dtsObj2.getCellData(1, "AFCHG_UNQ_ISU_ENG_NM"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "ISU_LIST_AMT", dtsObj2.getCellData(1, "AFCHG_LIST_AMT"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "LIST_DD", dtsObj2.getCellData(1, "STRT_DD"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "ISU_DD", dtsObj2.getCellData(1, "ISU_DD"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "ISUR_CD", dtsObj2.getCellData(1, "ISUR_CD"));
        if (dtsObj2.getCellData(1, "OBJ_INST_CD") != "") {
            dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "PRE_ISUR_CD", dtsObj2.getCellData(1, "OBJ_INST_CD"));
        } else {
            dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "PRE_ISUR_CD", "");
        }
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "BND_CLSS_CD", dtsObj2.getCellData(1, "AFCHG_BND_CLASS_CD"));
        dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "BND_TP_CD", dtsObj2.getCellData(1, "AFCHG_BND_TP_CD"));
    }
    dtsReqObj.setCellData(dtsReqObj.getFocusedRowIndex(), "VALID_STD_CD", dtsObj.getCellData(1, "VALID_STD_CD"));
    trsObj.Action = $c.lce.fn_encodeNSession(url);
    trsObj.KeyName = "toinb_dataid4";
    trsObj.KeyValue = "JSP(I:pInput=" + dtsReqObj.id + ")";
    trsObj.Post();
};


/******************************************************************* 
 * 함수명   : fn_CheckCmData
 * 설명     : 접수,처리완료,수정 시 체크항목 
 * argument : screnId, dtsObj, strtDd, bndApplId
 *******************************************************************/
/**
 * @method
 * @name fn_CheckCmData
 * @description desc
 * @param {string} screnId desc
 * @param {string} dtsObj desc
 * @param {string} strtDd desc
 * @param {string} bndApplId desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckCmData = function(screnId, dtsObj, strtDd, bndApplId) {
    dtsObj.SyncLoad = "true";
    dtsObj.DataID = encodeURI(scwin.fn_getCheckUrl(screnId, strtDd, bndApplId, 'N'));
    dtsObj.Reset();
    if (dtsObj.getCellData(1, "VALID_STRT_DD") == "Y") {
        alert("적용일이 현재일자보다 작습니다. 다시 입력하십시오.");
        return 1;
    }
    if (dtsObj.getCellData(1, "VALID_CALND_DD") == "Y") {
        alert("적용일이 매매일에 유효하지 않습니다. 다시 입력하십시오.");
        return 2;
    }
    //추가-적용일 전날이 아니면 확인메시지 보여주기
    if (dtsObj.getCellData(1, "VALID_BF_DD") == "Y") {
        if (!window.confirm("상장일/적용일이 익영업일이 아닙니다. 처리하시겠습니까?")) return 4;
    }
    if (dtsObj.getCellData(1, "VALID_CLS_DD") == "Y") {
        alert("입력한 일자는 이미 마감처리가 종료된 일자입니다. 다시 입력하십시오.");
        return 3;
    }
    return 0;
};


