 * 설명     : 신규,변경상장 수수료를 체크한다. 
 * argument : screnId, dtsObj, eachGp, bndApplId
 *******************************************************************/
/**
 * @method
 * @name fn_CheckFee
 * @description desc
 * @param {string} screnId desc
 * @param {string} eachGp desc
 * @param {string} dtsObj desc
 * @param {string} bndApplId desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckFee = function(screnId, eachGp, dtsObj, bndApplId) {
    dtsObj.SyncLoad = "true";
    dtsObj.DataID = encodeURI(scwin.fn_getCheckUrl(screnId, '', bndApplId, 'N'));
    dtsObj.Reset();
    if (eachGp == "1") {
        if (dtsObj.getCellData(1, "VALID_FEE_NEW") == "Y") {
            alert("수수료그룹지정이 안된종목입니다. 수수료그룹지정을 하십시오!");
            return 5;
        }
    } else if (eachGp == "2") {
        if (dtsObj.getCellData(1, "VALID_FEE_CHG") == "Y") {
            alert("수수료그룹지정이 안된종목입니다. 수수료그룹지정을 하십시오!");
            return 5;
        }
    }
    return 0;
};


