/******************************************************************* 
 * 함수명   : fn_HasAttachDoc
 * 설명     : 첨부문서 및 팩스문서를 체크한다.
 * argument : dataset, 채권신청번호, 처리구분코드
 *******************************************************************/
/**
 * @method
 * @name fn_HasAttachDoc
 * @description desc
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} vBndApplId desc
 * @param {string} vBndListProcsTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_HasAttachDoc = function(vScrenID, dtsObj, vBndApplId, vBndListProcsTpCd) {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + vBndApplId; //채권신청ID
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + vBndListProcsTpCd; //채권처리구분(1:신청,2:접수)

    //종목정보
    var dsNm = 'BNS_ATTACH_DOC';
    var qryId = 'lds.stf.bnscommon.select.readAttachDocYn';
    dtsObj.ClearData();
    dtsObj.SyncLoad = "true";
    scwin.fn_SearchBns(vScrenID, dtsObj, dsNm, qryId, param);
    if ("N" == dtsObj.getCellData(1, "HAS_ATTACH_DOC")) {
        alert("연결된 팩스/첨부문서가 없습니다.");
        return 1;
    }
    return 0;
};


