/******************************************************************* 
 * 함수명   : fn_getCheckUrl
 * 설명     : 접수,처리완료,수정 시 체크항목 URL을 리턴한다.
 * argument : screnId, strtDd, bndApplId, stdCdYn
 *******************************************************************/
/**
 * @method
 * @name fn_getCheckUrl
 * @description desc
 * @param {string} screnId desc
 * @param {string} strtDd desc
 * @param {string} bndApplId desc
 * @param {string} stdCdYn desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getCheckUrl = function(screnId, strtDd, bndApplId, stdCdYn) {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_CHECK_ITEM";
    url += "&queryId=lds.stf.bnscommon.select.readChkItemOfApplAcptAndCls";
    url += "&SCREN_ID=" + screnId;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_BND_APPL_ID=" + bndApplId;
    url += "&{P}V_STRT_DD=" + strtDd;
    url += "&{P}V_STD_CD_YN=" + stdCdYn;
    return url;
};


/******************************************************************* 
 * 함수명   : fn_CheckAcptProcStrtDd
 * 설명     : 접수처리/처리완료시 해당종목이 이미 조치일이 같은일자로 시장조치 대기중인지 체크 
 *				=> 320(일별금액조정), 201(상호변경), 일괄상장 연간등록 해당없음
 * argument : dtsObj, strtDd, bndApplId, stdCd
 *******************************************************************/
/**
 * @method
 * @name fn_CheckAcptProcStrtDd
 * @description desc
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} strtDd desc
 * @param {string} bndApplId desc
 * @param {string} isuCd desc
 * @param {string} processGp desc
 * @param {string} mktactTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckAcptProcStrtDd = function(vScrenID, dtsObj, strtDd, bndApplId, isuCd, processGp, mktactTpCd) {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + bndApplId;
    param += "&{P}V_STRT_DD=" + strtDd;
    param += "&{P}V_ISU_CD=" + isuCd;
    param += "&{P}V_MKTACT_TP_CD=" + mktactTpCd;
    var qryId = '';
    var dsNm = 'BNS_ACPT_STRT_DD_CHECK';
    if (processGp == "1") {
        //접수
        qryId = "lds.stf.bnscommon.select.acptStrtDdCheck";
    } else if (processGp == "3") {
        //처리완료
        qryId = "lds.stf.bnscommon.select.procStrtDdCheck";
    }
    dtsObj.SyncLoad = "true";
    scwin.fn_SearchBns(vScrenID, dtsObj, dsNm, qryId, param);
    return 0;
};


