/******************************************************************* 
 * 함수명   : fn_SetPopupPos
 * 설명     : 팝업 위치를 설정
 * argument : object
 *******************************************************************/
/**
 * @method
 * @name fn_SetPopupPos
 * @description desc
 * @param {string} grdObj desc
 * @param {string} Tg desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SetPopupPos = function(grdObj, Tg) {
    var cL = 7;
    var cT = 53;
    if (Tg == "G") {
        cL = 3;
        cT = 22;
    }
    scwin.obj_left = grdObj.style.left;
    scwin.obj_left = obj_left.substring(0, obj_left.length - 2);
    scwin.obj_left = eval(scwin.obj_left) + cL;
    scwin.obj_top = grdObj.style.top;
    scwin.obj_top = obj_top.substring(0, obj_top.length - 2);
    scwin.obj_top = eval(scwin.obj_top) + cT;
};


/******************************************************************* 
 * 함수명   : fn_SetAllCheckBox
 * 설명     : 전체 선택,취소를 설정한다.
 * argument : grdObj, dtsObj, bCheck
 *******************************************************************/
/**
 * @method
 * @name fn_SetAllCheckBox
 * @description desc
 * @param {string} grdObj desc
 * @param {string} dtsObj desc
 * @param {string} bCheck desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_SetAllCheckBox = function(grdObj, dtsObj, bCheck) {
    var vcd = "";
    if (bCheck == '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grdObj.setBroadcast(false);
    for (var i = 1; i <= dtsObj.getTotalRow(); i++) {
        dtsObj.setCellData(i, "CHECKED", vcd);
    }
    grdObj.setBroadcast(true);
};


/******************************************************************* 
 * 함수명   : fn_CheckAcptProcStripProcCfm
 * 설명     : 처리완료시 스트립 추가/재결합 처리완료 여부 확인
 * argument : dtsObj, strtDd, bndApplId, stdCd
 *******************************************************************/
/**
 * @method
 * @name fn_CheckAcptProcStripProcCfm
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} strtDd desc
 * @param {string} bndApplId desc
 * @param {string} isuCd desc
 * @param {string} bndListProcsTpCd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckAcptProcStripProcCfm = function(dtsObj, strtDd, bndApplId, isuCd, bndListProcsTpCd) {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_COM_CD";
    url += "&queryId=lds.stf.bnscommon.select.acptAndProcStipProcCfm";
    url += "&SCREN_ID=" + vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_BND_APPL_ID=" + bndApplId;
    url += "&{P}V_BND_LIST_PROCS_TP_CD=" + bndListProcsTpCd;
    url += "&{P}V_STRT_DD=" + strtDd;
    url += "&{P}V_ISU_CD=" + isuCd;
    dtsObj.SyncLoad = "true";
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
    return 0;
};


/******************************************************************* 
 * 함수명   : fn_ListFeeCall
 * 설명     : 상장수수료 계산
 * argument : LIST_AMT
 * TextBox 사용하는 경우, /js/prelistCommon.js 의 fn_SetComma(numstr) 함께 사용
 * 일괄채권 그룹지정 수수료 전용 
 * 	- 일부/전체 복사된 그리드의 상장금액 합계에 대한 수수료
 *******************************************************************/
/**
 * @method
 * @name fn_ListFeeCall
 * @description desc
 * @param {string} listAmt desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ListFeeCall = function(listAmt) {
    var fee = 0; //(단위 : 원)

    if (listAmt > 0 && listAmt < 1000000000) {
        //10억 미만
        fee = 100000; //10만

    } else if (listAmt >= 1000000000 && listAmt < 2000000000) {
        //10억 ~ 20억 미만
        fee = 150000; //15만

    } else if (listAmt >= 2000000000 && listAmt < 5000000000) {
        //20억 ~ 50억 미만
        fee = 300000; //30만

    } else if (listAmt >= 5000000000 && listAmt < 10000000000) {
        //50억 ~ 100억 미만
        fee = 700000; //70만

    } else if (listAmt >= 10000000000 && listAmt < 15000000000) {
        //100억 ~ 150억 미만
        fee = 1000000; //100만

    } else if (listAmt >= 15000000000 && listAmt < 25000000000) {
        //150억 ~ 250억 미만
        fee = 1200000; //120만

    } else if (listAmt >= 25000000000 && listAmt < 50000000000) {
        //250억 ~ 500억 미만
        fee = 1300000; //130만

    } else if (listAmt >= 50000000000 && listAmt < 100000000000) {
        //500억 ~ 1,000억 미만
        fee = 1400000; //140만

    } else if (listAmt >= 100000000000 && listAmt < 200000000000) {
        //1,000억 ~ 2,000억 미만
        fee = 1500000; //150만

    } else if (listAmt >= 200000000000 && listAmt < 500000000000) {
        //2,000억 ~ 5,000억 미만
        fee = 1600000; //160만

    } else if (listAmt >= 500000000000) {
        //5,000억 이상
        fee = 1700000; //170만

    }
    return fee;
};


