/************************************************************* 
* 함수명	: ShowWinArrPnl(arrPnl, sval)
* 설명	: 채권 신청정보 화면 로딩중 표시를 Display 한다.
		  (상단 그리드가 아닌 하단 그리드에 표시할 때 사용)
* param	: sval - grid ID
		  arrPnl - sval의 부모 Panel ID와 sval의 상위 Panel ID를 가지는 배열 변수 
		  (예: var arrPnl = [pnl_Acpt, pnl_AcptSrch];)
*************************************************************/
/**
 * @method
 * @name ShowWinArrPnl
 * @description desc
 * @param {string} arrPnl desc
 * @param {string} sval desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ShowWinArrPnl = async function(arrPnl, sval) {
    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
    var temTop = 0;
    for (var i = 0; i < arrPnl.length; i++) {
        temTop = temTop + Number((arrPnl[i].style.top).replace('px', ''));
        if (i > 0) {
            temTop = temTop + Number((arrPnl[i].style.getStyle("height")).replace('px', ''));
        }
    }
    temTop = temTop + 'px';
    var tem1 = sval.style.getStyle("width");
    var temLeft = sval.style.left;
    var tem2 = sval.style.getStyle("height");
    tem1 = tem1.substring(0, (tem1.length - 2));
    temLeft = temLeft.substring(0, (temLeft.length - 2));
    tem2 = tem2.substring(0, (tem2.length - 2));
    temTop = temTop.substring(0, (temTop.length - 2));
    vXpos = (eval(tem1 / 2) - 65) + Number(temLeft);
    vYpos = (eval(tem2 / 2) + 25) + Number(temTop);
    if ($c.frame.path("LoadingImg") == null) {
        await $c.frame.CreateFrame("LoadingImg", "/common/LoadingImg.gfm", "페이지 로딩중...", vXpos, vYpos, 130, 35, "sunken", 0, 0, true);
    }
};



/************************************************************* 
* 함수명	: CloseWinArrPnl()
* 설명	: Display 중인 화면 로딩중 표시를 닫는다.
		  (상단 그리드가 아닌 하단 그리드에 표시할 때 사용)
* param	: sval - grid ID
		  arrPnl - sval의 부모 Panel ID와 sval의 상위 Panel ID를 가지는 배열 변수 
		  (예: var arrPnl = [pnl_Acpt, pnl_AcptSrch];)
		  cnt - sval의 rowcount
*************************************************************/
/**
 * @method
 * @name CloseWinArrPnl
 * @description desc
 * @param {string} cnt desc
 * @param {string} arrPnl desc
 * @param {string} sval desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.CloseWinArrPnl = async function(cnt, arrPnl, sval) {
    if ($c.frame.path("LoadingImg") != null) {
        await $c.frame.CloseFrame();
        if (cnt == 0) scwin.ShowNoDataArrPnl(arrPnl, sval);
    }
};



