		//수정,처리완료,팀장확인 시 해당 ROW로 이동
		fn_RowPos(dts_List, vRowPos);	
****************************************************************************************/
/**
 * @method
 * @name fn_RowPos
 * @description desc
 * @param {string} dtsObj desc
 * @param {string} vRowPos desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_RowPos = function(dtsObj, vRowPos) {
    if (vRowPos.length != 12 && vRowPos > 0) {
        dtsObj.setFocusedCell(dtsObj.getTotalRow(), 0);
        dtsObj.setFocusedCell(vRowPos, 0);
    }
};



/*************************************************************
 * 함수명	: fn_CheckMultActImpsblRule
 * 설명		: 해당종목의 복수조치 건이 접수되어 있는지 체크
 * param		: vScrenID, vIsuCd, vMktactCd, vStrtDd
 *************************************************************/
/**
 * @method
 * @name fn_CheckMultActImpsblRule
 * @description desc
 * @param {string} vScrenID desc
 * @param {string} dtsObj desc
 * @param {string} vIsuCd desc
 * @param {string} vMktactCd desc
 * @param {string} vStrtDd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckMultActImpsblRule = function(vScrenID, dtsObj, vIsuCd, vMktactCd, vStrtDd) {
    var dsNm = 'BNS_MULTACT_IMPSBLE_RULE';
    var qryId = 'lds.stf.bnscommon.select.readMultActImpsblRule';
    var param = '';
    param += '&{P}V_STD_CD=' + vIsuCd;
    param += '&{P}V_BND_MKTACT_TP_CD=' + vMktactCd;
    param += '&{P}V_STRT_DD=' + vStrtDd;
    dtsObj.SyncLoad = "true";
    scwin.fn_SearchBns(vScrenID, dtsObj, dsNm, qryId, param);
    var output = '복수조치가 불가능한 시장조치입니다.';
    output += '\n' + '해당종목에 대하여 적용일이 동일한 신청내역을 검토하여 주십시오.';
    if (dtsObj.getCellData(1, 'MULTACT_IMPSBL_CNT') > 0) {
        alert(output);
        return 1;
    }
    return 0;
};


