/*******************************************************************
 * 함수명   : fn_CheckDateObj
 * 설명     : 날짜 유효성 체크
 * argument : obj - 날짜 object
 *            objNm - 날짜 object name
 *******************************************************************/
/**
 * @method
 * @name fn_CheckDateObj
 * @description desc
 * @param {string} obj desc
 * @param {string} objNm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_CheckDateObj = function(obj, objNm) {
    if (obj.getValue() == null || obj.getValue() == '') {
        return false;
    }
    var yyyy;
    var mm;
    var dd;
    yyyy = scwin.fn_Trim(obj.getValue().substring(0, 4)).replace(" ", "");
    mm = scwin.fn_Trim(obj.getValue().substring(4, 6));
    dd = scwin.fn_Trim(obj.getValue().substring(6, 8));
    if (yyyy == '' || yyyy.length < 4) {
        alert(objNm + " : 년을 제대로 입력해주세요.");
        obj.focus();
        return true;
    }
    var year = Number(yyyy);
    var month = Number(mm);
    var day = Number(dd);
    if (month == 1) total_days = 31;

    else if (month == 2) {
        if (((year % 4 == 0) && (year % 100 != 0)) || (year % 400 == 0)) total_days = 29;

        else total_days = 28;
    } else if (month == 3) total_days = 31;

    else if (month == 4) total_days = 30;

    else if (month == 5) total_days = 31;

    else if (month == 6) total_days = 30;

    else if (month == 7) total_days = 31;

    else if (month == 8) total_days = 31;

    else if (month == 9) total_days = 30;

    else if (month == 10) total_days = 31;

    else if (month == 11) total_days = 30;

    else if (month == 12) total_days = 31;

    else {
        alert(objNm + " : 존재하지 않는 월입니다.");
        obj.focus();
        return true;
    }
    if (year <= 0) {
        alert(objNm + " : 존재하지 않는 년도입니다.");
        obj.focus();
        return true;
    }
    if (month <= 0) {
        alert(objNm + " : 존재하지 않는 월입니다.");
        obj.focus();
        return true;
    }
    if (day > total_days) {
        alert(objNm + " : 존재하지 않는 날짜입니다.");
        obj.focus();
        return true;
    }
    if (day <= 0) {
        alert(objNm + " : 존재하지 않는 날짜입니다.");
        obj.focus();
        return true;
    }
    if (mm.length == 1) {
        alert(objNm + " : 존재하지 않는 월입니다.");
        obj.focus();
        return true;
    }
    if (dd.length == 1) {
        alert(objNm + " : 존재하지 않는 날짜입니다.");
        obj.focus();
        return true;
    }
    return false;
};


//문자열 앞뒤 공백 제거
/**
 * @method
 * @name fn_Trim
 * @description desc
 * @param {string} _str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_Trim = function(_str) {
    return _str.replace(/^\s{1,}/, "").replace(/\s{1,}$/, "");
};


/**********************************************
 * 함수명   : fn_AddCheck
 * 설명      : 고객 요청에의한 체크 추가 2024-06-05 by 김효준
 ***********************************************/
/**
 * @method
 * @name fn_AddCheck
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_AddCheck = function() {
    // 회사채 & 보증/담보 in (무보증,정부보증,부분보증) & (발행금액 or 상장금액 < 3억)
    if (dts_IsuInfo.getCellData(1, "BND_TP_CD") == "CO" &&
        (dts_IsuInfo.getCellData(1, "BND_GUAR_TP_CD") == "2" || dts_IsuInfo.getCellData(1, "BND_GUAR_TP_CD") == "4" || dts_IsuInfo.getCellData(1, "BND_GUAR_TP_CD") == "5") &&
        (dts_IsuInfo.getCellData(1, "ISU_AMT") < 300000000 || dts_IsuInfo.getCellData(1, "LIST_AMT") < 300000000)) {
        var msg = "무보증/정부보증/부분보증 회사채의 발행/상장금액이 3억원 미만으로 입력되었습니다.\n\n계속 진행하시겠습니까?";
        if (!window.confirm(msg)) return 1;
    }

    // 회사채 & 보증/담보 in (보증,담보부,커버드본드) & (발행금액 or 상장금액 < 5천만)
    if (dts_IsuInfo.getCellData(1, "BND_TP_CD") == "CO" &&
        (dts_IsuInfo.getCellData(1, "BND_GUAR_TP_CD") == "1" || dts_IsuInfo.getCellData(1, "BND_GUAR_TP_CD") == "3" || dts_IsuInfo.getCellData(1, "BND_GUAR_TP_CD") == "6") &&
        (dts_IsuInfo.getCellData(1, "ISU_AMT") < 50000000 || dts_IsuInfo.getCellData(1, "LIST_AMT") < 50000000)) {
        var msg = "보증/담보부/커버드본드 회사채의 발행/상장금액이 5천만원 미만으로 입력되었습니다.\n\n계속 진행하시겠습니까?";
        if (!window.confirm(msg)) return 1;
    }

    // 과세여부 비과세인경우.(대부분 과세)
    if (dts_IsuInfo.getCellData(1, "TAX_YN") == "N") {
        if (!window.confirm("과세여부가 \"비과세\"로 설정되어 있습니다.\n\n계속 진행하시겠습니까?")) return 1;
    }

    // 기명구분이 기명인경우.(대부분 무기명)
    if (dts_IsuInfo.getCellData(1, "SIGN_YN") == "Y") {
        if (!window.confirm("기명구분이 \"기명\"으로 설정되어 있습니다.\n\n계속 진행하시겠습니까?")) return 1;
    }
    var tmp = cmb_DebtRepayRankTpCd.getText();
    // 선/후/중순위가 선순위가 아닌경우.(대부분 선순위)
    if (dts_IsuInfo.getCellData(1, "DEBT_REPAY_RANK_TP_CD") != "1") {
        if (!window.confirm("선/후/중순위가 \"" + tmp + "\"으로 설정되어 있습니다.\n\n계속 진행하시겠습니까?")) return 1;
    }
    return 0;
};


/**********************************************
 * 함수명   : getBusinessDay
 * 설명     : 기준일로부터 영업일 기준으로 T-offPrev ~ T+offNext
 *           offPrev : 기준일로부터 offPrev 영업일 전. 항상 양수로 입력..
 *           offNext : 기준일로부터 offNext 영업일 후. 항상 양수로 입력..
 ***********************************************/
/**
 * @method
 * @name getBusinessDay
 * @description desc
 * @param {string} vScrenID desc
 * @param {string} vDataSet desc
 * @param {string} base_dt desc
 * @param {string} offPrev desc
 * @param {string} offNext desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getBusinessDay = function(vScrenID, vDataSet, base_dt, offPrev, offNext) {
    var param = '';
    param += "&{P}v_baseDt=" + base_dt;
    param += "&{P}v_offPrev=" + offPrev;
    param += "&{P}v_offNext=" + offNext;
    vDataSet.syncload = "true";
    var dsId = "BNS_BUSINESS_DAY_INFO";
    var qryId = "lds.stf.bnscommon.select.getBusinessDay";
    scwin.fn_SearchBns(vScrenID, vDataSet, dsId, qryId, param);
};
